// Build routing decision from ingest payload + template
const body = $('Ingest Webhook').item.json.body;
const template = $input.item.json[0] || {};

const missionId = body.mission_id;
const packageType = body.package_type;
const photoCount = body.photo_count || 0;
const videoCount = body.video_count || 0;
const hasPpk = body.has_ppk_data || false;
const platform = body.source_platform || 'unknown';
const missionFolderPath = body.mission_folder_path || '';
const pathCode = template.path_code || '';

// Determine which paths to run
const hasPhotos = photoCount > 0;
const hasVideo = videoCount > 0;

// Path C (mapping/photogrammetry) — packages that produce orthomosaics
const mappingPackages = ['construction_progress', 'commercial_basic', 'commercial_premium', 'insurance_claim', 'site_survey', 'environmental_survey'];
const runPathC = hasPhotos && mappingPackages.includes(packageType);

// Path E (vegetation) — from template or explicit flag
const vegetationEnabled = template.vegetation_enabled || false;
const vegetationConfig = template.vegetation_config || {};

return [
  {
    json: {
      mission_id: missionId,
      mission_folder_path: missionFolderPath,
      package_type: packageType,
      photo_count: photoCount,
      video_count: videoCount,
      has_ppk_data: hasPpk,
      source_platform: platform,
      path_code: pathCode,
      template_id: template.id || null,
      run_video: hasVideo,
      run_photos: hasPhotos,
      run_mapping: runPathC,
      run_vegetation: vegetationEnabled && runPathC,
      vegetation_config: vegetationConfig
    }
  }
];

// Build summary response
const routing = $('Build Routing Decision').item.json;

return [
  {
    json: {
      status: 'routed',
      mission_id: routing.mission_id,
      package_type: routing.package_type,
      paths_triggered: {
        video: routing.run_video,
        mapping: routing.run_mapping,
        vegetation: routing.run_vegetation
      },
      photo_count: routing.photo_count,
      video_count: routing.video_count
    }
  }
];

// Parse delivery output
const stdout = $input.item.json.stdout || '{}';
let result;
try {
  result = JSON.parse(stdout);
} catch (e) {
  throw new Error('delivery_packaging.py stdout is not valid JSON: ' + stdout.substring(0, 200));
}

if ($input.item.json.exitCode !== 0) {
  throw new Error('delivery_packaging.py failed with exit code ' + $input.item.json.exitCode);
}

return [{ json: result }];

// Return delivery confirmation
return [{
  json: {
    status: 'delivered',
    mission_id: $('Delivery Webhook').item.json.body.mission_id,
    zip_name: $('Delivery — Parse Result').item.json.zip_name,
    zip_size_mb: $('Delivery — Parse Result').item.json.zip_size_mb
  }
}];
